package tests.base;
import tests.BaseTest;
import io.github.ccxt.Helpers;
import io.github.ccxt.BaseExchange;
import io.github.ccxt.Exchange;
import java.util.HashMap;


// PLEASE DO NOT EDIT THIS FILE, IT IS GENERATED AND WILL BE OVERWRITTEN:
// https://github.com/ccxt/ccxt/blob/master/CONTRIBUTING.md#how-to-contribute-code

public class TestModPow extends BaseTest
{
        public void testModPow()
        {
            var exchange = new Exchange(new HashMap<String, Object>() {{
                put( "id", "sampleexchange" );
            }});
            // intToBase16 emits uppercase hex in some target languages, assign before toLowerCase (php transpiler)
            // small values
            Object small = exchange.modPow(exchange.convertToBigInt("4"), exchange.convertToBigInt("13"), exchange.convertToBigInt("497"));
            Object smallHexRaw = exchange.intToBase16(small);
            String smallHex = ((String)smallHexRaw).toLowerCase();
            Assert(java.util.Objects.equals(smallHex, "1bd"), ("modPow small failed, expected: 1bd, got: " + smallHex));
            // results above 2^64 must survive intToBase16 (the interactivebrokers diffie-hellman challenge is 2048-bit)
            // 2 ^ 100 mod (2 ^ 127 - 1) = 2 ^ 100
            Object modulus = exchange.convertToBigInt("0x7fffffffffffffffffffffffffffffff");
            Object big = exchange.modPow(exchange.convertToBigInt("2"), exchange.convertToBigInt("100"), modulus);
            Object bigHexRaw = exchange.intToBase16(big);
            String bigHex = ((String)bigHexRaw).toLowerCase();
            Assert(java.util.Objects.equals(bigHex, "10000000000000000000000000"), ("modPow big failed, expected: 10000000000000000000000000, got: " + bigHex));
            // 0xffffffffffffffffffff ^ 3 mod (2 ^ 127 - 1)
            Object base = exchange.convertToBigInt("0xffffffffffffffffffff");
            Object cubed = exchange.modPow(base, exchange.convertToBigInt("3"), modulus);
            Object cubedHexRaw = exchange.intToBase16(cubed);
            String cubedHex = ((String)cubedHexRaw).toLowerCase();
            Assert(java.util.Objects.equals(cubedHex, "200000002fffffffffff9ffffffff"), ("modPow cubed failed, expected: 200000002fffffffffff9ffffffff, got: " + cubedHex));
        }
}